import Foundation

extension Deck {
    /// The Suit of Wands — fire, will, passion, creativity, and action. Ids 22...35.
    static let wands: [TarotCard] = [
        TarotCard(id: 22, name: "Ace of Wands", arcana: .minor, suit: .wands, number: 1, element: .fire,
                  keywords: ["inspiration", "potential", "spark", "new venture"],
                  upright: "A spark of inspiration and raw creative energy ready to ignite. Seize the impulse and begin a passion-driven venture.",
                  reversed: "A stalled start or scattered enthusiasm. The spark is there but lacks direction — clarify what truly excites you."),
        TarotCard(id: 23, name: "Two of Wands", arcana: .minor, suit: .wands, number: 2, element: .fire,
                  keywords: ["planning", "decisions", "vision", "future"],
                  upright: "You hold the world in your hands and survey your options. Plan boldly and commit to a vision beyond the familiar.",
                  reversed: "Fear of the unknown or playing it too safe. Indecision keeps your potential on the shelf — choose a direction."),
        TarotCard(id: 24, name: "Three of Wands", arcana: .minor, suit: .wands, number: 3, element: .fire,
                  keywords: ["expansion", "foresight", "progress", "momentum"],
                  upright: "Your plans set sail and progress is in view; expansion rewards your foresight. Keep looking ahead with confidence.",
                  reversed: "Delays, setbacks, or a too-narrow horizon. Patience is needed — and perhaps a wider plan than the one you have."),
        TarotCard(id: 25, name: "Four of Wands", arcana: .minor, suit: .wands, number: 4, element: .fire,
                  keywords: ["celebration", "harmony", "home", "milestone"],
                  upright: "Joyful celebration, homecoming, and a milestone reached together. Pause to honor what you and yours have built.",
                  reversed: "A delayed celebration or tension on the home front. Harmony needs tending before the joy can fully arrive."),
        TarotCard(id: 26, name: "Five of Wands", arcana: .minor, suit: .wands, number: 5, element: .fire,
                  keywords: ["conflict", "competition", "tension", "rivalry"],
                  upright: "Lively conflict, competition, and clashing energies. Channel the friction into healthy effort rather than chaos.",
                  reversed: "Avoiding conflict or inner tension finally easing. Resolve the disagreement, or stop suppressing what needs to be said."),
        TarotCard(id: 27, name: "Six of Wands", arcana: .minor, suit: .wands, number: 6, element: .fire,
                  keywords: ["victory", "recognition", "confidence", "success"],
                  upright: "Well-earned victory and public recognition for your efforts. Accept the praise and let your confidence rise.",
                  reversed: "A lack of recognition or an ego in check. Success may be private now — keep going without the applause."),
        TarotCard(id: 28, name: "Seven of Wands", arcana: .minor, suit: .wands, number: 7, element: .fire,
                  keywords: ["defense", "perseverance", "conviction", "standing ground"],
                  upright: "Hold your ground and defend what you've built against challenge. Your conviction is worth standing up for.",
                  reversed: "Overwhelm, giving up, or feeling outnumbered. Reassess which battles are truly yours to fight."),
        TarotCard(id: 29, name: "Eight of Wands", arcana: .minor, suit: .wands, number: 8, element: .fire,
                  keywords: ["speed", "movement", "momentum", "news"],
                  upright: "Swift movement and rapid progress; news and events arrive quickly. Act now while the momentum is with you.",
                  reversed: "Delays, frustration, or things moving too fast to manage. Slow down enough to aim before you fire."),
        TarotCard(id: 30, name: "Nine of Wands", arcana: .minor, suit: .wands, number: 9, element: .fire,
                  keywords: ["resilience", "persistence", "boundaries", "last stand"],
                  upright: "Battle-worn but resilient, you stand firm near the finish. Summon your last reserves — you're closer than you think.",
                  reversed: "Exhaustion, paranoia, or refusing needed help. Lower your guard enough to rest and let support in."),
        TarotCard(id: 31, name: "Ten of Wands", arcana: .minor, suit: .wands, number: 10, element: .fire,
                  keywords: ["burden", "responsibility", "hard work", "overload"],
                  upright: "Carrying a heavy load of responsibility toward the goal. Honor the effort, but consider what you can set down.",
                  reversed: "Burnout from refusing to delegate or release. Put the weight down before it breaks you — you can't carry it all."),
        TarotCard(id: 32, name: "Page of Wands", arcana: .minor, suit: .wands, number: 11, element: .fire,
                  keywords: ["enthusiasm", "exploration", "curiosity", "new ideas"],
                  upright: "An eager messenger of inspiration and adventure. Explore a new interest with playful, fearless curiosity.",
                  reversed: "Restlessness or all spark and no follow-through. Ground your enthusiasm into something you'll actually finish."),
        TarotCard(id: 33, name: "Knight of Wands", arcana: .minor, suit: .wands, number: 12, element: .fire,
                  keywords: ["passion", "action", "adventure", "impulsiveness"],
                  upright: "Bold, passionate action and an appetite for adventure. Charge ahead with charisma — just keep one eye on the road.",
                  reversed: "Recklessness, hot-headedness, or projects abandoned mid-flight. Temper the fire with a little forethought."),
        TarotCard(id: 34, name: "Queen of Wands", arcana: .minor, suit: .wands, number: 13, element: .fire,
                  keywords: ["confidence", "warmth", "vivacity", "determination"],
                  upright: "Radiant confidence, warmth, and magnetic determination. Lead with courage and let your authentic fire draw others in.",
                  reversed: "Self-doubt, jealousy, or scattered energy. Reconnect with your own worth before comparing yourself to others."),
        TarotCard(id: 35, name: "King of Wands", arcana: .minor, suit: .wands, number: 14, element: .fire,
                  keywords: ["leadership", "vision", "boldness", "charisma"],
                  upright: "A visionary leader who inspires through bold, decisive action. Set the direction and rally others to your cause.",
                  reversed: "Impulsiveness, domineering, or grand plans without grounding. Lead by example, not by force or empty bravado.")
    ]
}
